   104→void UWjWorldGameRuleBase::OnGameEndPredict(float Seconds)
   105→{
   106→	if (!HasAuthority()) return;
   107→	if (GameMode.IsValid())
   108→	{
   109→		GameMode->EndGamePredict(Seconds);
   110→	}
   111→}
   112→
   113→void UWjWorldGameRuleBase::OnGameEnd()
   114→{
   115→	if (!HasAuthority()) return;
   116→
   117→	UWorld* World = GetWorld();
   118→	if (World)
   119→	{
   120→		// 세션 종료 (InProgress → Ended) - WaitingRoom 복귀 후 다시 StartSession 가능하게
   121→		if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(World->GetGameInstance()))
   122→		{
   123→			GI->EndGame();
   124→		}
   125→
   126→		// ServerTravel URL 미리 계산 (타이머 콜백에서 this 접근 문제 방지)
   127→		const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   128→		FString TravelURL = Settings->GetWaitingRoomServerTravelURL();
   129→
   130→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase::OnGameEnd - Will travel to: %s in %f seconds"), *TravelURL, SecondsForGotoWaitingRoom);
   131→
   132→		// Lobby 맵을 사용하되 GameMode는 WaitingRoom으로 오버라이드
   133→		// World를 WeakPtr로 캡처하여 타이머 콜백에서 안전하게 접근
   134→		TWeakObjectPtr<UWorld> WeakWorld = World;
   135→		World->GetTimerManager().SetTimer(GotoWaitingRoomHandle, FTimerDelegate::CreateLambda([WeakWorld, TravelURL]() {
   136→			if (UWorld* ValidWorld = WeakWorld.Get())
   137→			{
   138→				UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase - Executing ServerTravel to: %s"), *TravelURL);
   139→				ValidWorld->ServerTravel(TravelURL);
   140→			}
   141→			else
   142→			{
   143→				UE_LOG(LogWjWorld, Error, TEXT("GameRuleBase - ServerTravel failed: World is invalid"));
   144→			}
   145→		}), SecondsForGotoWaitingRoom, false);
   146→
   147→		ChangeGamePhase(EGamePhase::Finished);
   148→	}
   149→
   150→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Game Ended"));
   151→}
   152→
   153→void UWjWorldGameRuleBase::OnPlayerJoined(AWjWorldPlayerStatePlay* Player)
   154→{
   155→	if (!HasAuthority()) return;
   156→	if (!Player) return;
   157→
   158→	if (PlayerDataComponentClass)
   159→	{
   160→		Player->AddGameDataComponent(PlayerDataComponentClass);
   161→	}
   162→
   163→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Player Joined - %s"), *Player->GetName());
   164→}
   165→
   166→void UWjWorldGameRuleBase::OnPlayerLeft(AWjWorldPlayerStatePlay* Player)
   167→{
   168→	if (!HasAuthority()) return;
   169→}
   170→
   171→bool UWjWorldGameRuleBase::CheckWinCondition() const
   172→{
   173→	return false;
   174→}
   175→
   176→AWjWorldPlayerStatePlay* UWjWorldGameRuleBase::GetWinner() const
   177→{
   178→	return nullptr;
   179→}
   180→
   181→void UWjWorldGameRuleBase::TickGameRule(float DeltaTime)
   182→{
   183→	// 서브클래스에서 오버라이드
   184→}
   185→
   186→void UWjWorldGameRuleBase::BeginDestroy()
   187→{
   188→	Super::BeginDestroy();
   189→	
   190→	UWorld* World = GetWorld();
   191→	if (World)
   192→	{
   193→		World->GetTimerManager().ClearTimer(DelayStartHandle);
   194→		World->GetTimerManager().ClearTimer(GotoWaitingRoomHandle);
   195→	}
   196→}
   197→
   198→AWjWorldGameModePlay* UWjWorldGameRuleBase::GetGameModePlay() const
   199→{
   200→	UWorld* World = GetWorld();
   201→	if (World)
   202→	{
   203→		return World->GetAuthGameMode<AWjWorldGameModePlay>();
   204→	}
   205→	return nullptr;
   206→}
   207→
   208→AWjWorldGameStatePlay* UWjWorldGameRuleBase::GetGameStatePlay() const
   209→{
   210→	UWorld* World = GetWorld();
   211→	if (World)
   212→	{
   213→		return World->GetGameState<AWjWorldGameStatePlay>();
   214→	}
   215→	return nullptr;
   216→}
   217→
   218→void UWjWorldGameRuleBase::GameLevelUp(int32 NewLevel)
   219→{
   220→	if (!HasAuthority()) return;
   221→
   222→	AWjWorldGameModePlay* GameModePlay = GetGameModePlay();
   223→	if (GameModePlay)
   224→	{
   225→		GameModePlay->OnGameLevelUp(NewLevel);
   226→	}
   227→
   228→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Game Level Up to %d"), NewLevel);
   229→}
   230→
   231→void UWjWorldGameRuleBase::ChangeGamePhase(EGamePhase GamePhase)
   232→{
   233→	if (!HasAuthority()) return;
   234→
   235→	if (AWjWorldGameStatePlay* GameStatePlay = GetGameStatePlay())
   236→	{
   237→		GameStatePlay->SetGamePhase(GamePhase);
   238→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Game Phase changed to %d"), static_cast<int32>(GamePhase));
   239→	}
   240→}
