    89→UWjWorldGameDataComponent* AWjWorldGameStatePlay::AddGameDataComponent(TSubclassOf<UWjWorldGameDataComponent> InDataComponentClass)
    90→{
    91→	if (InDataComponentClass)
    92→	{
    93→		GameDataComponent = NewObject<UWjWorldGameDataComponent>(this, InDataComponentClass);
    94→		AddInstanceComponent(GameDataComponent);
    95→		GameDataComponent->RegisterComponent();
    96→		GameDataComponent->SetIsReplicated(true);
    97→
    98→		return GameDataComponent;
    99→	}
   100→
   101→	return nullptr;
   102→}
