   145→void AWjWorldGameModeWaitingRoom::StartGame()
   146→{
   147→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameModeWaitingRoom: Starting game..."));
   148→
   149→	// ⭐ GameState에서 현재 RoomSettings 가져오기 (UI에서 업데이트된 값)
   150→	FRoomSettings Settings;
   151→	AWjWorldGameStateWaitingRoom* WjGameState = GetGameState<AWjWorldGameStateWaitingRoom>();
   152→	if (WjGameState)
   153→	{
   154→		Settings = WjGameState->GetRoomSettings();
   155→	}
   156→
   157→	// ⭐ 최소 인원 검증 (ServerTravel 전에 차단)
   158→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   159→	if (DevSettings && !DevSettings->MinigameCatalog.IsNull())
   160→	{
   161→		UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
   162→		if (Catalog)
   163→		{
   164→			const FWjWorldMinigameDefinition* MinigameDef = Catalog->FindByGameModeId(FName(*Settings.GameMode));
   165→			if (MinigameDef && WjGameState)
   166→			{
   167→				int32 PlayerCount = WjGameState->GetPlayerCount();
   168→				if (PlayerCount < MinigameDef->MinimumPlayers)
   169→				{
   170→					UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: Not enough players (%d < %d) for %s"),
   171→						PlayerCount, MinigameDef->MinimumPlayers, *Settings.GameMode);
   172→					return;
   173→				}
   174→			}
   175→		}
   176→	}
   177→
   178→	// GameInstance를 통해 세션 시작
   179→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   180→	if (!GameInstance)
   181→	{
   182→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameModeWaitingRoom: GameInstance is null"));
   183→		return;
   184→	}
   185→
   186→	bool bSuccess = GameInstance->StartGame();
   187→	if (!bSuccess)
   188→	{
   189→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameModeWaitingRoom: Failed to start session"));
   190→		return;
   191→	}
   192→
   193→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameModeWaitingRoom: Session start initiated"));
   194→
   195→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: Using GameState settings - GameMode: '%s', Map: '%s'"),
   196→		*Settings.GameMode, *Settings.MapName);
   197→
   198→	if (!WjGameState && GameInstance->GetSessionManager())
   199→	{
   200→		// 폴백: SessionManager에서 가져오기
   201→		Settings = GameInstance->GetSessionManager()->GetLastRoomSettings();
   202→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: Fallback to SessionManager settings - GameMode: '%s', Map: '%s'"),
   203→			*Settings.GameMode, *Settings.MapName);
   204→	}
   205→
   206→	// 카탈로그에서 LevelPath 조회
   207→	FString TravelURL;
   208→	if (DevSettings && !DevSettings->MinigameCatalog.IsNull())
   209→	{
   210→		UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
   211→		if (Catalog)
   212→		{
   213→			const FWjWorldMinigameDefinition* Def = Catalog->FindByGameModeId(FName(*Settings.GameMode));
   214→			if (Def)
   215→			{
   216→				// LevelPath + GameMode 명시적 지정 + GameModeId 전달 (GameRule 조회용)
   217→				TravelURL = DevSettings->GetPlayServerTravelURL(Def->LevelPath, Settings.GameMode);
   218→
   219→				// MapOption을 URL 옵션으로 전달
   220→				if (!Settings.MapName.IsEmpty())
   221→				{
   222→					TravelURL += FString::Printf(TEXT("?MapOption=%s"), *Settings.MapName);
   223→				}
   224→
   225→				UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameModeWaitingRoom: Travel to '%s' (GameModeId: %s)"),
   226→					*TravelURL, *Settings.GameMode);
   227→			}
   228→			else
   229→			{
   230→				UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: GameModeId '%s' not found in catalog"), *Settings.GameMode);
   231→			}
   232→		}
   233→	}
   234→
   235→	// 폴백: 카탈로그에서 못 찾으면 기본 경로 사용
   236→	if (TravelURL.IsEmpty())
   237→	{
   238→		TravelURL = TEXT("/Game/Map/03-1_ApproachingWall");
   239→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: Using fallback travel URL: %s"), *TravelURL);
   240→	}
   241→
   242→	GetWorld()->ServerTravel(TravelURL);
   243→}
