    19→AWjWorldGameModePlay::AWjWorldGameModePlay()
    20→{
    21→	PrimaryActorTick.bCanEverTick = true;
    22→	PrimaryActorTick.bStartWithTickEnabled = true;
    23→
    24→	PlayerStateClass = AWjWorldPlayerStatePlay::StaticClass();
    25→	PlayerControllerClass = AWjWorldPlayerControllerPlay::StaticClass();
    26→	HUDClass = AWjWorldHUDPlay::StaticClass();
    27→	GameStateClass = AWjWorldGameStatePlay::StaticClass();
