   118→void UWaitingRoomHUDWidget::NativeDestruct()
   119→{
   120→	// 델리게이트 언바인딩
   121→	if (CachedGameState)
   122→	{
   123→		CachedGameState->OnRoomInfoChanged.RemoveDynamic(this, &UWaitingRoomHUDWidget::OnRoomInfoChanged);
   124→		CachedGameState->OnPlayerListChanged.RemoveDynamic(this, &UWaitingRoomHUDWidget::OnPlayerListChanged);
