   145→void UWaitingRoomHUDWidget::OnReadyClicked()
   146→{
   147→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Ready button clicked"));
   148→
   149→	// PlayerState의 준비 상태 토글
   150→	APlayerController* PC = GetOwningPlayer();
   151→	if (PC)
   152→	{
   153→		AWjWorldPlayerStateBase* PlayerState = PC->GetPlayerState<AWjWorldPlayerStateBase>();
   154→		if (PlayerState)
