   165→void UWaitingRoomHUDWidget::OnStartGameClicked()
   166→{
   167→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Start Game button clicked"));
   168→
   169→	// ⭐ 게임 시작 전에 현재 UI 설정을 자동으로 적용 (Apply Settings 버튼을 안 눌러도 반영되도록)
   170→	ApplyCurrentUISettings();
   171→
   172→	// GameMode의 StartGame 호출
   173→	AWjWorldGameModeWaitingRoom* GameMode = Cast<AWjWorldGameModeWaitingRoom>(GetWorld()->GetAuthGameMode());
   174→	if (GameMode)
   175→	{
   176→		GameMode->StartGame();
   177→	}
   178→	else
   179→	{
   180→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: Failed to get WjWorldGameModeWaitingRoom"));
