   184→void UWaitingRoomHUDWidget::OnLeaveClicked()
   185→{
   186→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Leave button clicked"));
   187→
   188→	// GameInstance를 통해 방 나가기
   189→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   190→	if (GameInstance)
   191→	{
   192→		bool bSuccess = GameInstance->LeaveRoom();
   193→		if (bSuccess)
   194→		{
   195→			UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Leaving room..."));
   196→
   197→			// 로비로 이동
   198→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   199→			UGameplayStatics::OpenLevel(GetWorld(), FName(*Settings->GetLobbyMapPath()));
   200→		}
   201→		else
   202→		{
   203→			UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: Failed to leave room"));
   204→		}
   205→	}
   206→	else
   207→	{
   208→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: GameInstance is null"));
   209→	}
   210→}
