   212→void UWaitingRoomHUDWidget::OnSettingsClicked()
   213→{
   214→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Settings button clicked"));
   215→
   216→	if (!SettingsWidgetClass)
   217→	{
   218→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: SettingsWidgetClass is not set"));
   219→		return;
   220→	}
   221→
   222→	// 이미 열려있으면 닫기
   223→	if (SettingsWidgetInstance && SettingsWidgetInstance->IsInViewport())
   224→	{
   225→		SettingsWidgetInstance->ClosePopup();
   226→		return;
   227→	}
   228→
   229→	// 인스턴스가 없으면 생성
   230→	if (!SettingsWidgetInstance)
   231→	{
   232→		SettingsWidgetInstance = CreateWidget<USettingsWidget>(GetOwningPlayer(), SettingsWidgetClass);
   233→	}
   234→
   235→	if (SettingsWidgetInstance)
