   241→void UWaitingRoomHUDWidget::OnRoomInfoChanged(const FRoomSettings& RoomSettings)
   242→{
   243→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Room info changed event received - GameMode: %s, Map: %s"),
   244→		*RoomSettings.GameMode, *RoomSettings.MapName);
   245→
   246→	// ⭐ 직접 전달받은 설정으로 UI 업데이트 (타이밍 이슈 방지)
   247→	UpdateRoomInfo(&RoomSettings);
   248→
   249→	// 호스트 설정 패널의 ComboBox 선택도 업데이트 (초기화 타이밍 이슈 해결)
   250→	if (GameModeComboBox && !RoomSettings.GameMode.IsEmpty())
   251→	{
   252→		GameModeComboBox->SetSelectedOption(RoomSettings.GameMode);
   253→		UpdateMapComboBoxForGameMode(RoomSettings.GameMode);
   254→
   255→		// 맵 선택도 업데이트
   256→		if (MapComboBox && !RoomSettings.MapName.IsEmpty())
   257→		{
   258→			for (const auto& Pair : MapOptionDisplayToValue)
   259→			{
   260→				if (Pair.Value == RoomSettings.MapName)
   261→				{
   262→					MapComboBox->SetSelectedOption(Pair.Key);
   263→					break;
   264→				}
   265→			}
   266→		}
   267→	}
   268→}
