   431→void UWaitingRoomHUDWidget::ShowPlayerProfile(int32 PlayerID)
   432→{
   433→	if (!CachedGameState)
   434→	{
   435→		return;
   436→	}
   437→
   438→	// PlayerID로 PlayerState 검색
   439→	APlayerState* TargetPS = nullptr;
   440→	for (APlayerState* PS : CachedGameState->PlayerArray)
   441→	{
   442→		if (PS && PS->GetPlayerId() == PlayerID)
   443→		{
   444→			TargetPS = PS;
   445→			break;
   446→		}
   447→	}
   448→
   449→	if (!TargetPS)
   450→	{
   451→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: PlayerState not found for ID %d"), PlayerID);
   452→		return;
   453→	}
   454→
   455→	// 프로필 위젯 생성
   456→	if (!ProfileWidgetClass)
   457→	{
   458→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: ProfileWidgetClass is not set"));
   459→		return;
   460→	}
   461→
   462→	if (!ProfileWidgetInstance)
   463→	{
   464→		ProfileWidgetInstance = CreateWidget<UPlayerProfileWidget>(GetOwningPlayer(), ProfileWidgetClass);
   465→		if (ProfileWidgetInstance)
   466→		{
   467→			ProfileWidgetInstance->AddToViewport(100);
   468→		}
   469→	}
   470→
   471→	if (!ProfileWidgetInstance)
   472→	{
   473→		return;
   474→	}
   475→
   476→	// 자기 자신인지 확인
   477→	APlayerController* LocalPC = GetOwningPlayer();
   478→	if (LocalPC && LocalPC->PlayerState && LocalPC->PlayerState->GetPlayerId() == PlayerID)
   479→	{
   480→		// 자기 자신 → ShowLocalProfile
   481→		ProfileWidgetInstance->ShowLocalProfile();
   482→	}
   483→	else
   484→	{
   485→		// 타 플레이어
   486→		AWjWorldPlayerStateBase* BasePS = Cast<AWjWorldPlayerStateBase>(TargetPS);
   487→		FUniqueNetIdRepl UniqueId = TargetPS->GetUniqueId();
   488→		FText PlayerName = FText::FromString(TargetPS->GetPlayerName());
   489→		FCosmeticLoadout Loadout;
   490→		if (BasePS)
   491→		{
   492→			Loadout = BasePS->GetCosmeticLoadout();
   493→		}
   494→
   495→		ProfileWidgetInstance->ShowPlayerProfile(UniqueId, PlayerName, Loadout);
   496→	}
   497→
   498→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: ShowPlayerProfile for ID %d"), PlayerID);
   499→}
