   630→void UWaitingRoomHUDWidget::UpdateHostSettingsPanelVisibility()
   631→{
   632→	if (!HostSettingsPanel)
   633→	{
   634→		return;
   635→	}
   636→
   637→	bool bIsHost = false;
   638→
   639→	// 1. SessionManager에서 호스트 여부 확인
   640→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   641→	if (GameInstance && GameInstance->GetSessionManager())
   642→	{
   643→		bIsHost = GameInstance->GetSessionManager()->IsHost();
   644→	}
   645→
   646→	// 2. 추가 검증: Listen Server인지 확인 (클라이언트에서 잘못된 bIsHost 값 방지)
   647→	UWorld* World = GetWorld();
   648→	if (World)
   649→	{
   650→		ENetMode NetMode = World->GetNetMode();
   651→		// 클라이언트(NM_Client)는 절대 호스트가 아님
   652→		if (NetMode == NM_Client)
   653→		{
   654→			bIsHost = false;
   655→		}
   656→		// Listen Server(NM_ListenServer)만 호스트임
   657→		else if (NetMode == NM_ListenServer || NetMode == NM_DedicatedServer)
   658→		{
   659→			// SessionManager 값 유지
   660→		}
   661→		else if (NetMode == NM_Standalone)
   662→		{
   663→			// 싱글플레이는 호스트 설정 불필요
   664→			bIsHost = false;
   665→		}
   666→	}
   667→
   668→	// 호스트만 설정 패널 표시 (클라이언트는 Display Text로 확인)
   669→	HostSettingsPanel->SetVisibility(bIsHost ? ESlateVisibility::Visible : ESlateVisibility::Collapsed);
   670→
   671→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: HostSettingsPanel visible=%s (bIsHost=%d, NetMode=%d)"),
   672→		bIsHost ? TEXT("Yes") : TEXT("No"), bIsHost, World ? (int32)World->GetNetMode() : -1);
   673→}
