   675→void UWaitingRoomHUDWidget::UpdateMapComboBoxForGameMode(const FString& GameModeId)
   676→{
   677→	if (!MapComboBox)
   678→	{
   679→		return;
   680→	}
   681→
   682→	MapComboBox->ClearOptions();
   683→	MapOptionDisplayToValue.Empty();
   684→
   685→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   686→	if (!DevSettings || DevSettings->MinigameCatalog.IsNull())
   687→	{
   688→		return;
   689→	}
   690→
   691→	UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
   692→	if (!Catalog)
   693→	{
   694→		return;
   695→	}
   696→
   697→	const FWjWorldMinigameDefinition* Def = Catalog->FindByGameModeId(FName(*GameModeId));
   698→	if (Def)
   699→	{
   700→		for (const FWjWorldMinigameMapOption& Option : Def->MapOptions)
   701→		{
   702→			FString DisplayName = Option.DisplayName.ToString();
   703→			FString OptionValue = Option.OptionValue;
   704→
   705→			MapComboBox->AddOption(DisplayName);
   706→			MapOptionDisplayToValue.Add(DisplayName, OptionValue);
   707→		}
   708→	}
   709→
   710→	// ApproachingWall인 경우 유저 레이아웃도 추가
   711→	if (GameModeId == TEXT("ApproachingWall"))
   712→	{
   713→		if (!DevSettings->WallDescriptionAsset.IsNull())
   714→		{
   715→			UWjWorldWallDescriptionDataAsset* WallAsset = DevSettings->WallDescriptionAsset.LoadSynchronous();
   716→			if (WallAsset)
   717→			{
   718→				TArray<FWjWorldWallDescription> UserLayouts;
   719→				WallAsset->ScanUserWallLayouts(UserLayouts);
   720→
   721→				for (const FWjWorldWallDescription& Layout : UserLayouts)
   722→				{
   723→					FString DisplayName = Layout.WallName;
   724→					DisplayName.RemoveFromStart(TEXT("User_"));
   725→					FString DisplayStr = FString::Printf(TEXT("[User] %s"), *DisplayName);
   726→
   727→					MapComboBox->AddOption(DisplayStr);
   728→					MapOptionDisplayToValue.Add(DisplayStr, Layout.WallName);
   729→				}
   730→
   731→				UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Added %d AW user layouts"), UserLayouts.Num());
   732→			}
   733→		}
   734→	}
   735→
   736→	// JumpMap인 경우 유저 레이아웃도 추가
   737→	if (GameModeId == TEXT("JumpMap"))
   738→	{
   739→		if (!DevSettings->JumpMapLayoutDataAsset.IsNull())
   740→		{
   741→			UJumpMapLayoutDataAsset* LayoutAsset = DevSettings->JumpMapLayoutDataAsset.LoadSynchronous();
   742→			if (LayoutAsset)
   743→			{
   744→				TArray<FJumpMapLayout> UserLayouts;
   745→				LayoutAsset->ScanUserJumpMapLayouts(UserLayouts);
   746→
   747→				for (const FJumpMapLayout& Layout : UserLayouts)
   748→				{
   749→					FString DisplayName = Layout.LayoutName;
   750→					DisplayName.RemoveFromStart(TEXT("User_"));
   751→					FString DisplayStr = FString::Printf(TEXT("[User] %s"), *DisplayName);
   752→
   753→					MapComboBox->AddOption(DisplayStr);
   754→					MapOptionDisplayToValue.Add(DisplayStr, Layout.LayoutName);
   755→				}
   756→
   757→				UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Added %d JumpMap user layouts"), UserLayouts.Num());
   758→			}
   759→		}
   760→	}
   761→
   762→	if (MapComboBox->GetOptionCount() > 0)
   763→	{
   764→		MapComboBox->SetSelectedIndex(0);
   765→	}
   766→
   767→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Map options updated for GameMode '%s' - %d options"),
   768→		*GameModeId, MapComboBox->GetOptionCount());
   769→}
