   782→void UWaitingRoomHUDWidget::OnApplySettingsClicked()
   783→{
   784→	UE_LOG(LogWjWorld, Warning, TEXT("=== WaitingRoomHUDWidget::OnApplySettingsClicked START ==="));
   785→
   786→	if (!CachedGameState)
   787→	{
   788→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: CachedGameState is NULL!"));
   789→		return;
   790→	}
   791→	if (!GameModeComboBox)
   792→	{
   793→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: GameModeComboBox is NULL!"));
   794→		return;
   795→	}
   796→	if (!MapComboBox)
   797→	{
   798→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: MapComboBox is NULL!"));
   799→		return;
   800→	}
   801→
   802→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   803→	if (!GameInstance || !GameInstance->GetSessionManager() || !GameInstance->GetSessionManager()->IsHost())
   804→	{
   805→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Only host can change settings (IsHost=%d)"),
   806→			GameInstance && GameInstance->GetSessionManager() ? GameInstance->GetSessionManager()->IsHost() : false);
   807→		return;
   808→	}
   809→
   810→	FRoomSettings OldSettings = CachedGameState->GetRoomSettings();
   811→	FRoomSettings NewSettings = OldSettings;
   812→
   813→	FString SelectedGameMode = GameModeComboBox->GetSelectedOption();
   814→	NewSettings.GameMode = SelectedGameMode;
   815→
   816→	FString SelectedMapDisplay = MapComboBox->GetSelectedOption();
   817→	if (const FString* MapValue = MapOptionDisplayToValue.Find(SelectedMapDisplay))
   818→	{
   819→		NewSettings.MapName = *MapValue;
   820→	}
   821→	else
   822→	{
   823→		NewSettings.MapName = SelectedMapDisplay;
   824→	}
   825→
   826→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Applying settings change:"));
   827→	UE_LOG(LogWjWorld, Warning, TEXT("  GameMode: '%s' -> '%s'"), *OldSettings.GameMode, *NewSettings.GameMode);
   828→	UE_LOG(LogWjWorld, Warning, TEXT("  MapName: '%s' -> '%s'"), *OldSettings.MapName, *NewSettings.MapName);
   829→
   830→	CachedGameState->UpdateRoomSettings(NewSettings);
   831→
   832→	// ⭐ 호스트 로컬에서 Display Text 직접 업데이트 (델리게이트 타이밍 안전장치)
   833→	UpdateRoomInfo(&NewSettings);
   834→
   835→	UE_LOG(LogWjWorld, Warning, TEXT("=== WaitingRoomHUDWidget::OnApplySettingsClicked END ==="));
   836→}
