    33→void UGA_Grapple::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, const FGameplayEventData* TriggerEventData)
    34→{
    35→	Super::ActivateAbility(Handle, ActorInfo, ActivationInfo, TriggerEventData);
    36→
    37→	// EndAbility 호출용 캐시
    38→	CachedHandle = Handle;
    39→	CachedActorInfo = ActorInfo;
    40→	CachedActivationInfo = ActivationInfo;
    41→
    42→	if (HasAuthorityOrPredictionKey(ActorInfo, &ActivationInfo))
    43→	{
    44→		ACharacter* Character = Cast<ACharacter>(ActorInfo->AvatarActor.Get());
    45→		if (!Character)
    46→		{
    47→			EndAbility(Handle, ActorInfo, ActivationInfo, true, true);
    48→			return;
    49→		}
    50→
    51→		APlayerController* PC = Cast<APlayerController>(Character->GetController());
    52→		if (!PC)
    53→		{
    54→			EndAbility(Handle, ActorInfo, ActivationInfo, true, true);
    55→			return;
    56→		}
    57→
    58→		// 카메라 방향으로 라인 트레이스
    59→		FVector CamLoc;
    60→		FRotator CamRot;
    61→		PC->GetPlayerViewPoint(CamLoc, CamRot);
    62→
    63→		FVector TraceEnd = CamLoc + CamRot.Vector() * GrappleRange;
    64→		FHitResult HitResult;
    65→		FCollisionQueryParams Params;
    66→		Params.AddIgnoredActor(Character);
    67→
    68→		if (GetWorld()->LineTraceSingleByChannel(HitResult, CamLoc, TraceEnd, ECC_WorldStatic, Params))
    69→		{
    70→			AJumpMapGrapplePointActor* GrapplePoint = Cast<AJumpMapGrapplePointActor>(HitResult.GetActor());
    71→			if (GrapplePoint)
    72→			{
    73→				if (!CommitAbility(Handle, ActorInfo, ActivationInfo))
    74→				{
    75→					EndAbility(Handle, ActorInfo, ActivationInfo, true, true);
    76→					return;
    77→				}
    78→
    79→				GrappleTargetLocation = GrapplePoint->GetActorLocation();
    80→				bIsPulling = true;
    81→
    82→				// 캐릭터를 타겟 방향으로 발사
    83→				FVector Direction = (GrappleTargetLocation - Character->GetActorLocation()).GetSafeNormal();
    84→				Character->LaunchCharacter(Direction * GrapplePullSpeed, true, true);
    85→
    86→				UE_LOG(LogWjWorldAbilities, Log, TEXT("GA_Grapple: Pulling %s toward %s"),
    87→					*Character->GetName(), *GrappleTargetLocation.ToString());
    88→
    89→				// 도착 체크 타이머 (매 틱)
    90→				if (UWorld* World = GetWorld())
    91→				{
    92→					ArrivalCheckTimerHandle = World->GetTimerManager().SetTimerForNextTick(
    93→						FTimerDelegate::CreateUObject(this, &UGA_Grapple::CheckArrival));
    94→				}
    95→				return;
    96→			}
    97→		}
    98→
    99→		// 미스 → 쿨다운 없이 종료
   100→		EndAbility(Handle, ActorInfo, ActivationInfo, true, false);
   101→	}
   102→}
