   104→void UGA_Grapple::EndAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, bool bReplicateEndAbility, bool bWasCancelled)
   105→{
   106→	bIsPulling = false;
   107→
   108→	// 타이머 정리
   109→	if (UWorld* World = GetWorld())
   110→	{
   111→		World->GetTimerManager().ClearTimer(ArrivalCheckTimerHandle);
   112→	}
   113→
   114→	Super::EndAbility(Handle, ActorInfo, ActivationInfo, bReplicateEndAbility, bWasCancelled);
   115→}
