   117→void UGA_Grapple::CheckArrival()
   118→{
   119→	if (!bIsPulling)
   120→	{
   121→		return;
   122→	}
   123→
   124→	if (!CachedActorInfo || !CachedActorInfo->AvatarActor.IsValid())
   125→	{
   126→		bIsPulling = false;
   127→		EndAbility(CachedHandle, CachedActorInfo, CachedActivationInfo, true, true);
   128→		return;
   129→	}
   130→
   131→	ACharacter* Character = Cast<ACharacter>(CachedActorInfo->AvatarActor.Get());
   132→	if (!Character)
   133→	{
   134→		bIsPulling = false;
   135→		EndAbility(CachedHandle, CachedActorInfo, CachedActivationInfo, true, true);
   136→		return;
   137→	}
   138→
   139→	float Distance = FVector::Dist(Character->GetActorLocation(), GrappleTargetLocation);
   140→	if (Distance <= ArrivalThreshold)
   141→	{
   142→		bIsPulling = false;
   143→		EndAbility(CachedHandle, CachedActorInfo, CachedActivationInfo, true, false);
   144→		return;
   145→	}
   146→
   147→	// 아직 이동 중 → 다음 틱에 다시 체크
   148→	if (UWorld* World = GetWorld())
   149→	{
   150→		ArrivalCheckTimerHandle = World->GetTimerManager().SetTimerForNextTick(
   151→			FTimerDelegate::CreateUObject(this, &UGA_Grapple::CheckArrival));
   152→	}
   153→}
