   655→bool USessionManager::FindMigrationSession(const FString& MigrationTag)
   656→{
   657→	if (!SessionInterface.IsValid())
   658→	{
   659→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: SessionInterface is invalid"));
   660→		return false;
   661→	}
   662→
   663→	PendingMigrationTag = MigrationTag;
   664→
   665→	// 검색 설정
   666→	SessionSearch = MakeShareable(new FOnlineSessionSearch());
   667→	SessionSearch->MaxSearchResults = 50;
   668→
   669→	// 네트워크 모드에 따른 검색 설정 (LastRoomSettings에서 가져옴)
   670→	if (LastRoomSettings.NetworkMode == ENetworkMode::Steam)
   671→	{
   672→		SessionSearch->bIsLanQuery = false;
   673→		SessionSearch->QuerySettings.Set(SEARCH_LOBBIES, true, EOnlineComparisonOp::Equals);
   674→	}
   675→	else // LAN
   676→	{
   677→		SessionSearch->bIsLanQuery = true;
   678→		SessionSearch->QuerySettings.Set(SEARCH_LOBBIES, false, EOnlineComparisonOp::Equals);
   679→	}
   680→
   681→	// 검색 시작
   682→	const ULocalPlayer* LocalPlayer = GetWorld()->GetFirstLocalPlayerFromController();
   683→	bool bSuccess = SessionInterface->FindSessions(*LocalPlayer->GetPreferredUniqueNetId(), SessionSearch.ToSharedRef());
   684→
   685→	if (bSuccess)
   686→	{
   687→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Searching for migration session with tag '%s'"), *MigrationTag);
   688→	}
   689→	else
   690→	{
   691→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Failed to start migration session search"));
   692→	}
   693→
   694→	return bSuccess;
   695→}
