   164→void UWjWorldGameInstance::HandleNetworkFailure(UWorld* World, UNetDriver* NetDriver,
   165→	ENetworkFailure::Type FailureType, const FString& ErrorString)
   166→{
   167→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: HandleNetworkFailure called - Type: %d, Error: %s"),
   168→		static_cast<int32>(FailureType), *ErrorString);
   169→
   170→	// 이미 마이그레이션 중이면 무시
   171→	if (MigrationContext.bIsMigrating)
   172→	{
   173→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: NetworkFailure ignored - already migrating"));
   174→		return;
   175→	}
   176→
   177→	// 자신이 호스트(서버)면 마이그레이션 불필요
   178→	if (World && World->GetAuthGameMode() != nullptr)
   179→	{
   180→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure on server - ignoring (Type: %d, Error: %s)"),
   181→			static_cast<int32>(FailureType), *ErrorString);
   182→		return;
   183→	}
   184→
   185→	// 연결 관련 Failure 타입은 모두 마이그레이션 시도
   186→	// (Steam P2P에서는 다양한 에러 타입이 발생할 수 있음)
   187→	switch (FailureType)
   188→	{
   189→	case ENetworkFailure::ConnectionLost:
   190→	case ENetworkFailure::FailureReceived:
   191→	case ENetworkFailure::ConnectionTimeout:
   192→	case ENetworkFailure::PendingConnectionFailure:
   193→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: NetworkFailure detected - Type: %d, Error: %s. Beginning host migration."),
   194→			static_cast<int32>(FailureType), *ErrorString);
   195→		BeginHostMigration();
   196→		break;
   197→	default:
   198→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure type %d not handled for migration"),
   199→			static_cast<int32>(FailureType));
   200→		break;
   201→	}
   202→}
