   204→void UWjWorldGameInstance::HandleTravelFailure(UWorld* World, ETravelFailure::Type FailureType, const FString& ErrorString)
   205→{
   206→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: HandleTravelFailure called - Type: %d, Error: %s"),
   207→		static_cast<int32>(FailureType), *ErrorString);
   208→
   209→	// 이미 마이그레이션 중이면 무시
   210→	if (MigrationContext.bIsMigrating)
   211→	{
   212→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: TravelFailure ignored - already migrating"));
   213→		return;
   214→	}
   215→
   216→	// 자신이 호스트(서버)면 마이그레이션 불필요
   217→	if (World && World->GetAuthGameMode() != nullptr)
   218→	{
   219→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: TravelFailure on server - ignoring"));
   220→		return;
   221→	}
   222→
   223→	// ServerTravel 실패 시 호스트 마이그레이션 시도
   224→	switch (FailureType)
