   233→		break;
   234→	default:
   235→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: TravelFailure type %d not handled for migration"),
   236→			static_cast<int32>(FailureType));
   237→		break;
   238→	}
   239→}
