   243→// ============================================================================
   244→
   245→void UWjWorldGameInstance::BeginHostMigration()
   246→{
   247→	MigrationContext.bIsMigrating = true;
   248→	MigrationContext.MigrationStartTime = FPlatformTime::Seconds();
   249→	MigrationContext.RetryCount = 0;
   250→	SetMigrationState(EHostMigrationState::Detected);
   251→
   252→	// 마이그레이션 태그 생성 (모든 클라이언트 동일)
   253→	MigrationContext.MigrationSessionTag = GenerateMigrationTag();
   254→
   255→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Host migration started - Tag: '%s'"),
   256→		*MigrationContext.MigrationSessionTag);
   257→
   258→	// 기존 세션 파괴
   259→	if (SessionManager)
   260→	{
   261→		SessionManager->DestroySession();
   262→	}
   263→
   264→	// 타임아웃 타이머 설정
   265→	UWorld* World = GetWorld();
   266→	if (World)
   267→	{
   268→		World->GetTimerManager().SetTimer(MigrationTimeoutHandle,
   269→			FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::OnMigrationTimeout),
   270→			FHostMigrationContext::MigrationTimeout, false);
   271→	}
   272→
   273→	// 새 호스트 결정
   274→	MigrationContext.bIsNewHost = DetermineIfNewHost();
   275→
   276→	if (MigrationContext.bIsNewHost)
   277→	{
   278→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: This client is the new host"));
   279→		MigrationCreateSession();
   280→	}
   281→	else
   282→	{
   283→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: This client is NOT the new host - waiting 3s before searching"));
   284→
   285→		// 3초 대기 후 검색 시작
   286→		if (World)
   287→		{
   288→			World->GetTimerManager().SetTimer(MigrationRetryHandle,
   289→				FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::MigrationSearchForNewHost),
   290→				3.0f, false);
   291→		}
   292→	}
   293→}
