   295→bool UWjWorldGameInstance::DetermineIfNewHost() const
   296→{
   297→	const TArray<FPlayerDisplayInfo>& CachedPlayers = MigrationContext.CachedPlayerList;
   298→
   299→	if (CachedPlayers.Num() == 0)
   300→	{
   301→		// 캐시가 비어있으면 자신이 호스트
   302→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: No cached players - assuming new host"));
   303→		return true;
   304→	}
   305→
   306→	// PlayerID 오름차순 정렬 (이전 호스트 제외)
   307→	TArray<FPlayerDisplayInfo> Candidates;
   308→	for (const FPlayerDisplayInfo& Info : CachedPlayers)
   309→	{
   310→		if (!Info.bIsHost) // 이전 호스트 제외
   311→		{
   312→			Candidates.Add(Info);
   313→		}
   314→	}
   315→
   316→	if (Candidates.Num() == 0)
   317→	{
   318→		// 모든 플레이어가 호스트? 자신이 새 호스트
   319→		return true;
   320→	}
   321→
   322→	// PlayerID 오름차순 정렬
   323→	Candidates.Sort([](const FPlayerDisplayInfo& A, const FPlayerDisplayInfo& B)
   324→	{
   325→		return A.PlayerID < B.PlayerID;
   326→	});
   327→
   328→	// 첫 번째 = 새 호스트
   329→	return (Candidates[0].PlayerID == MigrationContext.LocalPlayerID);
   330→}
