   332→FString UWjWorldGameInstance::GenerateMigrationTag() const
   333→{
   334→	// 결정론적 태그: "MIG_{RoomName}_{OriginalHostPlayerID}"
   335→	FString RoomName = MigrationContext.CachedRoomSettings.RoomName;
   336→	int32 OriginalHostID = -1;
   337→
   338→	for (const FPlayerDisplayInfo& Info : MigrationContext.CachedPlayerList)
   339→	{
   340→		if (Info.bIsHost)
   341→		{
   342→			OriginalHostID = Info.PlayerID;
   343→			break;
   344→		}
   345→	}
   346→
   347→	return FString::Printf(TEXT("MIG_%s_%d"), *RoomName, OriginalHostID);
   348→}
