   350→void UWjWorldGameInstance::MigrationCreateSession()
   351→{
   352→	SetMigrationState(EHostMigrationState::CreatingSession);
   353→
   354→	if (!SessionManager)
   355→	{
   356→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: MigrationCreateSession - SessionManager is null"));
   357→		MigrationFailed();
   358→		return;
   359→	}
   360→
   361→	// 콜백 바인딩
   362→	SessionManager->OnRoomCreatedEvent.AddDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   363→
   364→	bool bSuccess = SessionManager->CreateMigrationSession(
   365→		MigrationContext.CachedRoomSettings,
   366→		MigrationContext.MigrationSessionTag);
   367→
   368→	if (!bSuccess)
   369→	{
   370→		SessionManager->OnRoomCreatedEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   371→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Failed to create migration session"));
   372→		MigrationRetryOrFail();
   373→	}
