   376→void UWjWorldGameInstance::OnMigrationSessionCreated(bool bWasSuccessful)
   377→{
   378→	if (SessionManager)
   379→	{
   380→		SessionManager->OnRoomCreatedEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   381→	}
   382→
   383→	if (bWasSuccessful)
   384→	{
   385→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration session created - ServerTraveling to WaitingRoom"));
   386→		SetMigrationState(EHostMigrationState::Complete);
   387→
   388→		UWorld* World = GetWorld();
   389→		if (World)
   390→		{
