   392→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   393→			World->ServerTravel(Settings->GetWaitingRoomOpenLevelURL());
   394→		}
   395→	}
   396→	else
   397→	{
   398→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration session creation failed"));
