   427→void UWjWorldGameInstance::OnMigrationSearchResult(bool bWasSuccessful, const TArray<FRoomInfo>& Rooms)
   428→{
   429→	if (SessionManager)
   430→	{
   431→		SessionManager->OnRoomsFoundEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   432→	}
   433→
   434→	if (bWasSuccessful)
   435→	{
   436→		// JoinSession은 FindMigrationSession 내부에서 자동으로 호출됨
   437→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration session found and joining"));
   438→		SetMigrationState(EHostMigrationState::JoiningSession);
   439→
   440→		UWorld* World = GetWorld();
   441→		if (World)
   442→		{
   443→			World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   444→		}
   445→		// JoinSession → ClientTravel이 자동으로 발생
   446→	}
   447→	else
   448→	{
   449→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: Migration session not found - will retry"));
   450→		MigrationRetryOrFail();
   451→	}
