   453→
   454→void UWjWorldGameInstance::MigrationRetryOrFail()
   455→{
   456→	MigrationContext.RetryCount++;
   457→
   458→	// 타임아웃 체크
   459→	double ElapsedTime = FPlatformTime::Seconds() - MigrationContext.MigrationStartTime;
   460→	if (ElapsedTime >= FHostMigrationContext::MigrationTimeout)
   461→	{
   462→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration timed out after %.1f seconds"), ElapsedTime);
   463→		MigrationFailed();
   464→		return;
   465→	}
   466→
   467→	// 최대 재시도 횟수 체크
   468→	if (MigrationContext.RetryCount >= FHostMigrationContext::MaxRetryCount)
   469→	{
   470→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration max retries (%d) reached"), FHostMigrationContext::MaxRetryCount);
   471→		MigrationFailed();
   472→		return;
   473→	}
   474→
   475→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration retry %d/%d in %.1f seconds"),
   476→		MigrationContext.RetryCount, FHostMigrationContext::MaxRetryCount, FHostMigrationContext::RetryInterval);
   477→
   478→	UWorld* World = GetWorld();
   479→	if (World)
   480→	{
   481→		if (MigrationContext.bIsNewHost)
   482→		{
   483→			World->GetTimerManager().SetTimer(MigrationRetryHandle,
   484→				FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::MigrationCreateSession),
   485→				FHostMigrationContext::RetryInterval, false);
   486→		}
   487→		else
   488→		{
   489→			World->GetTimerManager().SetTimer(MigrationRetryHandle,
   490→				FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::MigrationSearchForNewHost),
   491→				FHostMigrationContext::RetryInterval, false);
   492→		}
   493→	}
   494→}
