   496→void UWjWorldGameInstance::OnMigrationTimeout()
   497→{
   498→	UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration timeout (%.0f seconds)"),
   499→		FHostMigrationContext::MigrationTimeout);
   500→	MigrationFailed();
   501→}
