   503→void UWjWorldGameInstance::MigrationFailed()
   504→{
   505→	SetMigrationState(EHostMigrationState::Failed);
   506→
   507→	UWorld* World = GetWorld();
   508→	if (World)
   509→	{
   510→		World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   511→		World->GetTimerManager().ClearTimer(MigrationRetryHandle);
   512→	}
   513→
   514→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: Migration failed - returning to lobby"));
   515→
   516→	// 세션 정리
   517→	if (SessionManager)
   518→	{
   519→		SessionManager->DestroySession();
   520→	}
   521→
   522→	// 마이그레이션 컨텍스트 리셋
   523→	MigrationContext.Reset();
   524→	SetMigrationState(EHostMigrationState::None);
   525→
   526→	// 로비로 복귀
   527→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   528→	UGameplayStatics::OpenLevel(this, FName(*Settings->GetLobbyMapPath()));
   529→}
