   234→bool UCreateRoomWindow::ValidateInput(FString& OutErrorMessage)
   235→{
   236→	// 방 이름 검사
   237→	if (!RoomNameTextBox)
   238→	{
   239→		OutErrorMessage = TEXT("Room name field is missing");
   240→		return false;
   241→	}
   242→
   243→	FString RoomName = RoomNameTextBox->GetText().ToString();
   244→	if (RoomName.IsEmpty())
   245→	{
   246→		OutErrorMessage = TEXT("방 이름을 입력해주세요");
   247→		return false;
   248→	}
   249→
   250→	if (RoomName.Len() > 20)
   251→	{
   252→		OutErrorMessage = TEXT("방 이름은 20자 이내로 입력해주세요");
   253→		return false;
   254→	}
   255→
   256→	// 비공개 방인 경우 비밀번호 검사
   257→	if (PrivateCheckBox && PrivateCheckBox->IsChecked())
   258→	{
   259→		if (PasswordTextBox)
   260→		{
   261→			FString Password = PasswordTextBox->GetText().ToString();
   262→			if (Password.IsEmpty())
   263→			{
   264→				OutErrorMessage = TEXT("비공개 방은 비밀번호를 입력해주세요");
   265→				return false;
   266→			}
   267→
   268→			if (Password.Len() < 4)
   269→			{
   270→				OutErrorMessage = TEXT("비밀번호는 4자 이상 입력해주세요");
   271→				return false;
   272→			}
   273→		}
   274→	}
   275→
   276→	// 게임 모드 검사
   277→	if (!GameModeComboBox || GameModeComboBox->GetSelectedOption().IsEmpty())
   278→	{
   279→		OutErrorMessage = TEXT("게임 모드를 선택해주세요");
   280→		return false;
   281→	}
   282→
   283→	// 맵 검사
   284→	if (!MapComboBox || MapComboBox->GetSelectedOption().IsEmpty())
   285→	{
   286→		OutErrorMessage = TEXT("맵을 선택해주세요");
   287→		return false;
   288→	}
   289→
   290→	return true;
   291→}
