   158→void URoomListWindow::OnNetworkModeSelectionChanged(FString SelectedItem, ESelectInfo::Type SelectionType)
   159→{
   160→	// 프로그램적 변경은 무시 (ShowPopupWithNetworkMode에서 설정할 때)
   161→	if (SelectionType == ESelectInfo::Direct)
