/**
 * 검색된 방 정보 (UI 표시용)
 */
USTRUCT(BlueprintType)
struct FRoomInfo
{
	GENERATED_BODY()

	/** 방 이름 */
	UPROPERTY(BlueprintReadOnly, Category = "Room")
	FString RoomName;

