	UPROPERTY(BlueprintReadOnly, Category = "Room")
	FString GameMode;

	/** 핑 */
	UPROPERTY(BlueprintReadOnly, Category = "Room")
	int32 Ping = 0;

	/** 게임 진행 중 여부 */
	UPROPERTY(BlueprintReadOnly, Category = "Room")
	bool bInProgress = false;

	/** 방장 이름 */
	UPROPERTY(BlueprintReadOnly, Category = "Room")
	FString HostName;

