   697→FRoomInfo USessionManager::ConvertSearchResultToRoomInfo(const FOnlineSessionSearchResult& SearchResult, int32 Index)
   698→{
   699→	FRoomInfo RoomInfo;
   700→
   701→	// 기본 정보
   702→	RoomInfo.SearchResultIndex = Index;
   703→	
   704→	// ⭐ 수정: 플레이어 수 계산
   705→	// NumOpenPublicConnections = 열린 슬롯 수
   706→	// 현재 플레이어 = 전체 - 열린 슬롯
   707→	int32 MaxPlayers = SearchResult.Session.SessionSettings.NumPublicConnections;
   708→	int32 OpenSlots = SearchResult.Session.NumOpenPublicConnections;
   709→	
   710→	RoomInfo.MaxPlayers = MaxPlayers;
   711→	RoomInfo.CurrentPlayers = MaxPlayers - OpenSlots;
   712→	
   713→	// ⭐ 최소 1명 보장 (호스트)
   714→	if (RoomInfo.CurrentPlayers <= 0)
   715→	{
   716→		RoomInfo.CurrentPlayers = 1;
   717→	}
   718→	
   719→	RoomInfo.Ping = SearchResult.PingInMs;
   720→
   721→	// 커스텀 데이터
   722→	SearchResult.Session.SessionSettings.Get(FName("ROOM_NAME"), RoomInfo.RoomName);
   723→	SearchResult.Session.SessionSettings.Get(FName("GAME_MODE"), RoomInfo.GameMode);
   724→	SearchResult.Session.SessionSettings.Get(FName("IS_PRIVATE"), RoomInfo.bIsPrivate);
   725→
   726→	// 호스트 이름
   727→	if (SearchResult.Session.OwningUserName.IsEmpty())
   728→	{
   729→		RoomInfo.HostName = TEXT("Unknown");
   730→	}
   731→	else
   732→	{
   733→		RoomInfo.HostName = SearchResult.Session.OwningUserName;
   734→	}
   735→
   736→	// 진행 상태
   737→	RoomInfo.bInProgress = SearchResult.Session.SessionSettings.bAllowJoinInProgress && (RoomInfo.CurrentPlayers > 0);
   738→
   739→	return RoomInfo;
   740→}
