   169→void UCreateRoomWindow::OnCreateClicked()
   170→{
   171→	UE_LOG(LogWjWorld, Log, TEXT("CreateRoomWindow: Create clicked"));
   172→
   173→	// 입력 유효성 검사
   174→	FString ErrorMessage;
   175→	if (!ValidateInput(ErrorMessage))
   176→	{
   177→		UE_LOG(LogWjWorld, Warning, TEXT("CreateRoomWindow: Validation failed - %s"), *ErrorMessage);
   178→		// TODO: 에러 메시지 UI 표시
   179→		return;
   180→	}
   181→
   182→	// RoomSettings 생성
   183→	FRoomSettings Settings = BuildRoomSettings();
   184→
   185→	// GameInstance를 통해 방 생성
   186→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   187→	if (GameInstance)
   188→	{
   189→		bool bSuccess = GameInstance->CreateRoom(Settings);
   190→		if (bSuccess)
