   123→void URoomListWindow::UpdateRoomList(const TArray<FRoomInfo>& Rooms)
   124→{
   125→	if (!RoomListScrollBox)
   126→	{
   127→		UE_LOG(LogWjWorld, Error, TEXT("RoomListWindow: RoomListScrollBox is null"));
   128→		return;
   129→	}
   130→
   131→	if (!RoomListEntryWidgetClass)
   132→	{
   133→		UE_LOG(LogWjWorld, Error, TEXT("RoomListWindow: RoomListEntryWidgetClass is not set"));
   134→		return;
   135→	}
   136→
   137→	// 기존 목록 제거
   138→	RoomListScrollBox->ClearChildren();
   139→
   140→	// 방이 없으면 메시지 표시
   141→	if (Rooms.Num() == 0)
   142→	{
   143→		UE_LOG(LogWjWorld, Warning, TEXT("RoomListWindow: No rooms found"));
   144→		// TODO: "방이 없습니다" 텍스트 표시
   145→		return;
   146→	}
   147→
   148→	// 각 방에 대한 엔트리 위젯 생성
   149→	for (const FRoomInfo& RoomInfo : Rooms)
   150→	{
   151→		URoomListEntryWidget* EntryWidget = CreateWidget<URoomListEntryWidget>(GetWorld(), RoomListEntryWidgetClass);
   152→		if (EntryWidget)
   153→		{
   154→			EntryWidget->SetRoomInfo(RoomInfo);
   155→			RoomListScrollBox->AddChild(EntryWidget);
   156→		}
   157→	}
   158→
   159→	UE_LOG(LogWjWorld, Log, TEXT("RoomListWindow: Room list updated with %d entries"), Rooms.Num());
   160→}
